export function createTiles(){


	var groundTiles, surfaceTiles, floodTiles, countMap;
	
	var mapData, elevationMap, floodData, surfaceMap;

	var cluster;

	var maxElevation, minElevation;

	var tileSize = 100;
	var numberOfTiles = 5625;
	var numberOfTiles_X = Math.pow(numberOfTiles, 0.5)
	var side_length = numberOfTiles_X * tileSize;
	var elevationGround = 100;

	var pos_of_objects = [];

	mapData = mapDataManual();
	elevationMap = elevationMapManual();
	floodData = floodManual();
	surfaceMap = surfaceManual();

	maxElevation = findMaximum(elevationMap);
	minElevation = findMinimum(elevationMap);

	console.log(minElevation, maxElevation);

	groundTiles = [];
	surfaceTiles = [];
	floodTiles = [];

	countMap = {};

	countMap["g1"] = 0;
	countMap["b1"] = 0;
	countMap["w1"] = 0;
	countMap["c1"] = 0;
	countMap["f1"] = 0;
	countMap["p1"] = 0;
	countMap["road1"] = 0;
	countMap["road2"] = 0;
	countMap["r1"] = 0;
	countMap["y1"] = 0;
	countMap["b2"] = 0;
	countMap["b3"] = 0;
	countMap["t1"] = 0;

	for (var row = 0; row < 140; row++){
		groundTiles.push([]);
		surfaceTiles.push([]);
		floodTiles.push([]);
		for (var column = 0; column < 55; column++){
			groundTiles[row].push(0);
			surfaceTiles[row].push(0);
			floodTiles[row].push(0);
		};
	};

	for (var row = 0; row < 140; row++){
		for (var column = 0; column < 55; column++){

			cluster = mapData[row][column];

			if (cluster == 1){
				//yesil tile
				groundTiles[row][column] = new groundTile(
					row,
					column,
					minMax(elevationMap[row][column], minElevation, maxElevation) - 20,
					"w1",
					row * 100 + column);
				countMap["w1"]++;
			}

			else if (cluster == 7){
				//road

				groundTiles[row][column] = new groundTile(
					row,
					column,
					minMax(elevationMap[row][column], minElevation, maxElevation),
					"road2",
					row * 100 + column)
				countMap["road2"]++;

			}

			else if (cluster == 6){
				//bina ve yesil tile
				groundTiles[row][column] = new groundTile(
					row,
					column,
					minMax(elevationMap[row][column], minElevation, maxElevation),
					"c1",
					row * 100 + column);
				countMap["c1"]++;

				/*
				
				if ((row % 3 == 0 
					&&
					column % 2 == 0) 
					){

					pos_of_objects.push([row, column]);
					surfaceTiles[row][column] = new surfaceTile(
						row,
						column,
						6,
						elevationGround,
						groundTiles[row][column].elevation,
						"b1",
						0)
					countMap["b1"]++;				
				};
				*/
				/*
				if (Math.random() > 0.8){
					pos_of_objects.push([row, column])
					surfaceTiles[row][column] = new surfaceTile(
						row,
						column,
						6,
						elevationGround,
						groundTiles[row][column].elevation,
						"b1",
						0)
					countMap["b1"]++;
				};
				*/

			}
			else if (cluster == 5){
				//yesil tile
				groundTiles[row][column] = new groundTile(
					row,
					column,
					minMax(elevationMap[row][column], minElevation, maxElevation),
					"r1",
					row * 100 + column);
				countMap["r1"]++;
				
				/*
				if ((row % 3 == 0 
					&&
					column % 2 == 0)
					){
					pos_of_objects.push([row, column])
					surfaceTiles[row][column] = new surfaceTile(
						row,
						column,
						6,
						elevationGround,
						groundTiles[row][column].elevation,
						"b2",
						0)
					countMap["b2"]++;					
				}
				*/				
				/*
				if (Math.random() > 0.8){
					pos_of_objects.push([row, column])
					surfaceTiles[row][column] = new surfaceTile(
						row,
						column,
						6,
						elevationGround,
						groundTiles[row][column].elevation,
						"b2",
						0)
					countMap["b2"]++;
				};
				*/

			}
			else if (cluster == 4){
				//water
				groundTiles[row][column] = new groundTile(
					row,
					column,
					minMax(elevationMap[row][column], minElevation, maxElevation),
					"road1",
					row * 100 + column)
				countMap["road1"]++;

			}

			else if (cluster == 3){
				//park (yard)

				groundTiles[row][column] = new groundTile(
					row,
					column,
					minMax(elevationMap[row][column], minElevation, maxElevation),
					"y1",
					row * 100 + column)
				countMap["y1"]++;
				/*
				if ((row % 3 == 0 
					&&
					column % 2 == 0)
					){
					pos_of_objects.push([row, column])
					surfaceTiles[row][column] = new surfaceTile(
						row,
						column,
						6,
						elevationGround,
						groundTiles[row][column].elevation,
						"b3",
						0)
					countMap["b3"]++;
				};
				*/

				/*				
				if (Math.random() > 0.8){
					pos_of_objects.push([row, column])
					surfaceTiles[row][column] = new surfaceTile(
						row,
						column,
						6,
						elevationGround,
						groundTiles[row][column].elevation,
						"b3",
						0)
					countMap["b3"]++;
				};
				*/

			}
			else if (cluster == 2){
				//bina ve yesil tile
				groundTiles[row][column] = new groundTile(
					row,
					column,
					minMax(elevationMap[row][column], minElevation, maxElevation),
					"g1",
					row * 100 + column);
				countMap["g1"]++;

			}
			else{
				//park (yard)
				groundTiles[row][column] = new groundTile(
					row,
					column,
					minMax(elevationMap[row][column], minElevation, maxElevation),
					"g1",
					row * 100 + column)
				countMap["g1"]++;

			};
		}
	}



	for (var i = 0; i < floodData.length; i++){

		

		var row, column;

		[row, column] = floodData[i];
		var temporalValue = minMax(75, minElevation, maxElevation) - groundTiles[row][column].elevation + 5;
		if (temporalValue > 0){
			floodTiles[row][column] = new floodTile(
				"f1",
				row,
				column,
				temporalValue,
				groundTiles[row][column].elevation,
				10,
				row + column);
			countMap["f1"]++;
		};
	};

	for ( var i = 0; i < surfaceMap.length; i++){

		var roww, columnn, typee;

		[roww, columnn, typee] = surfaceMap[i];

		pos_of_objects.push([roww, columnn])
		surfaceTiles[roww][columnn] = new surfaceTile(
			roww,
			columnn,
			6,
			elevationGround,
			groundTiles[roww][columnn].elevation,
			typee,
			0)
		countMap[typee]++;
	};

	return [groundTiles, surfaceTiles, floodTiles, pos_of_objects, countMap, floodData, minElevation, maxElevation];

};


function getRandomArbitrary(min=80, max=120) {
	return Math.random() * (max - min) + min;
};


function groundTile (row, column, elevation, type, instanceId){
	this.row  = row;
	this.column = column;
	this.elevation = elevation;
	this.type = type;
	this.instanceId = instanceId;
	this.elevateStructure = 0;
	this.sandbag = 0;
	this.floodWall = 0;
	this.floodInsurance = false;
};

function surfaceTile(row, column, size, height, elevation, type, instanceId, peopleOnIt=50){
	this.row  = row;
	this.column = column;
	this.elevation = elevation;
	this.type = type;
	this.instanceId = instanceId;
	this.height = height;
	this.size = size;
	this.floodInsurance = false;
	this.peopleOnIt = peopleOnIt;
};


function floodTile(type, row, column, height, elevation, size, instanceId){
	this.type = type;
	this.row  = row;
	this.column = column;
	this.elevation = elevation;
	this.instanceId = instanceId;
	this.height = height;
	this.size = size;
};

