function minMax(value, minElevation, maxElevation, min=10, max=150){
	var normalizedValue;

	normalizedValue = Math.floor(((value - minElevation) / (maxElevation - minElevation)) * (max - min) + min + Math.random() * 2) ;
	//normalizedValue = value;
	return normalizedValue;
};


function findMinimum(elevationDict){

	var minElevation = 10000000;

	for (name of Object.keys(elevationDict)){
		for (var i = 0; i < elevationDict[name].length; i++){
			if (elevationDict[name][i] < minElevation){
				minElevation = elevationDict[name][i];
			}
		};
	};

	return Math.max(minElevation - 2, 1);
};

function findMaximum(elevationDict){

	var maxElevation = 1;

	for (name of Object.keys(elevationDict)){
		for (var i = 0; i < elevationDict[name].length; i++){
			if (elevationDict[name][i] > maxElevation){
				maxElevation = elevationDict[name][i];
			}
		}
	};

	return maxElevation + 2;
};